		public bool addPokeSickAtRandom(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam, global::Pml.PokePara.Sick[] pSickTable, byte sickTableSize) {
			BTL_POKEPARAM attacker = pEffectParam.GetAttacker();
			var accessor = new FrontPokeAccessor(GetMainModule(), GetBattleEnv());
			bool isEffected = false;
			BTL_POKEPARAM target;
			while (accessor.GetNext(out target))
			{
				if (CheckFriendPoke(attacker, target))
					continue;
				Sick sick = pSickTable[(byte)calc.GetRand(sickTableSize)];
				BTL_SICKCONT sickCont = calc.MakeDefaultPokeSickCont(sick, attacker.GetID(), false);
				isEffected |= addSick(pEffectParam, target, (WazaSick)sick, new BTL_SICKCONTOBJ(sickCont), null);
			}
			return isEffected;
		}
