		private bool addSick(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam, global::Dpr.Battle.Logic.BTL_POKEPARAM pTarget, global::Pml.WazaData.WazaSick sick, global::Dpr.Battle.Logic.BTL_SICKCONTOBJ pSickCont, global::Dpr.Battle.Logic.StrParam pMessage) {
			bool isNeedSummarize = pEffectParam.IsNeedSummarize();
			BTL_POKEPARAM attacker = pEffectParam.GetAttacker();
			if (sick == WazaSick.WAZASICK_BIND)
			{
				GetEventLauncher().Event_WazaSickCont(attacker, pTarget, WazaSick.WAZASICK_BIND, pSickCont);
			}
			else if (sick == WazaSick.WAZASICK_MEROMERO)
			{
				byte attackerSex = (byte)attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_SEX);
				byte targetSex = (byte)pTarget.GetValue(BTL_POKEPARAM.ValueID.BPP_SEX);
				if (attackerSex == targetSex)
					return false;
				if (attackerSex == (byte)Pml.Sex.UNKNOWN)
					return false;
				if (targetSex == (byte)Pml.Sex.UNKNOWN)
					return false;
			}

			var desc = new Section_AddSick.Description();
			desc.pokeID = attacker.GetID();
			desc.targetPokeID = pTarget.GetID();
			desc.sickID = sick;
			desc.sickCont = pSickCont.value;
			desc.sickCause = SickCause.OTHER;
			desc.overWriteMode = SickOverWriteMode.CANT;
			desc.isEffectDisplay = !isNeedSummarize;
			desc.isFailResultDisplay = false;
			desc.isStandardMessageDisable = isNeedSummarize;
			if (pMessage != null)
				desc.specialMessage.CopyFrom(pMessage);
			if (sick == WazaSick.WAZASICK_TOOSENBOU && !isNeedSummarize)
			{
				desc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, (ushort)BTL_STRID_SET.CantEscWaza);
				desc.specialMessage.AddArg(pTarget.GetID());
			}
			var result = new Section_AddSick.Result();
			GetSectionContainer().GetSection_AddSick().Execute(result, desc);
			if (!result.isSuccessed)
				return false;
			pEffectParam.SetEffected_Sick(GetPokePos(pTarget), sick);
			return result.isSuccessed;
		}
