				return false;
			BTL_POKEPARAM attacker = pEffectParam.GetAttacker();
			int level = attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_LEVEL);
			uint useCount = attacker.PERMCOUNTER_Get(BTL_POKEPARAM.PermCounter.GSHOCK_NEKONIKOBAN_USE_COUNT);
			GetMainModule().AddBonusMoney((uint)level * (useCount + 1) * 100);
			GetServerCommandPutter().Message_Std((ushort)BTL_STRID_STD.NekoNiKoban);
			GetServerCommandPutter().IncPokePermCounter(attacker.GetID(), BTL_POKEPARAM.PermCounter.GSHOCK_NEKONIKOBAN_USE_COUNT);
			return true;
		}
