			return addSick_AllEnemies(pEffectParam, WazaSick.WAZASICK_ICHAMON, new BTL_SICKCONTOBJ(sickCont));
		}
		private bool effect_Syuukaku(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam) {
			if (calc.GetRand(2) == 0)
				return false;
			BTL_POKEPARAM attacker = pEffectParam.GetAttacker();
			var accessor = new FrontPokeAccessor(GetMainModule(), GetBattleEnv());
			bool isEffected = false;
			BTL_POKEPARAM target;
			while (accessor.GetNext(out target))
			{
				if (CheckFriendPoke(attacker, target))
					isEffected |= effect_Syuukaku_Target(target);
			}
			return isEffected;
		}
		private bool effect_Syuukaku_Target(global::Dpr.Battle.Logic.BTL_POKEPARAM pTarget) {
			ushort consumedItem = pTarget.GetConsumedItem();
			if (consumedItem == 0 || !Pml.Item.ItemData.IsNuts(consumedItem) || pTarget.GetItem() != 0)
				return false;
			byte pokeID = pTarget.GetID();
			var desc = new Section_FromEvent_SetItem.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = pokeID;
			desc.itemID = consumedItem;
			desc.isClearConsume = true;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, (ushort)BTL_STRID_SET.Recycle);
			desc.successMessage.AddArg(pokeID);
			desc.successMessage.AddArg(consumedItem);
			var result = new Section_FromEvent_SetItem.Result();
			GetSectionContainer().GetSection_FromEvent_SetItem().Execute(result, desc);
			return result.isSucceeded;
		}
		private bool effect_Sunazigoku(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam) {
			byte turns = (byte)(calc.GetRand(2) + 5);
			BTL_SICKCONT sickCont = SICKCONT.MakeTurnParam(pEffectParam.GetAttacker().GetID(), turns, (ushort)Pml.WazaNo.SUNAZIGOKU);
			return addSick_AllEnemies(pEffectParam, WazaSick.WAZASICK_BIND, new BTL_SICKCONTOBJ(sickCont));
		}
