		private bool effect_KiriBarai(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam) {
			byte attackerPokeID = pEffectParam.GetAttacker().GetID();
			byte defenderPokeID = pEffectParam.GetDefender().GetID();

			var defenderSideDesc = new Section_SideEffect_Remove.Description();
			defenderSideDesc.pokeID = attackerPokeID;
			defenderSideDesc.side = GetPokeSide(defenderPokeID);
			calc.BITFLG_Construction(defenderSideDesc.flags);
			for (byte i = 0; i < (byte)BtlSideEffect.BTL_SIDEEFF_MAX; i++)
			{
				if (tables.IsKiriBaraiEnable_DefenderSide((BtlSideEffect)i))
					calc.BITFLG_Set(defenderSideDesc.flags, i);
			}
			var defenderSideResult = new Section_SideEffect_Remove.Result();
			GetSectionContainer().GetSection_SideEffect_Remove().Execute(defenderSideResult, defenderSideDesc);
			bool isDefenderSideRemoved = defenderSideResult.isSuccessed;

			var attackerSideDesc = new Section_SideEffect_Remove.Description();
			attackerSideDesc.pokeID = attackerPokeID;
			attackerSideDesc.side = GetPokeSide(attackerPokeID);
			calc.BITFLG_Construction(attackerSideDesc.flags);
			for (byte i = 0; i < (byte)BtlSideEffect.BTL_SIDEEFF_MAX; i++)
			{
				if (tables.IsKiriBaraiEnable_AttackerSide((BtlSideEffect)i))
					calc.BITFLG_Set(attackerSideDesc.flags, i);
			}
			var attackerSideResult = new Section_SideEffect_Remove.Result();
			GetSectionContainer().GetSection_SideEffect_Remove().Execute(attackerSideResult, attackerSideDesc);
			bool isAttackerSideRemoved = attackerSideResult.isSuccessed;

			var groundDesc = new Section_FieldEffect_End.Description();
			groundDesc.effect = EffectType.EFF_GROUND;
			var groundResult = new Section_FieldEffect_End.Result();
			GetSectionContainer().GetSection_FieldEffect_End().Execute(groundResult, groundDesc);
			return isDefenderSideRemoved | isAttackerSideRemoved | groundResult.isRemoved;
		}
		private bool effect_CureSick(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam) {
			bool isNeedSummarize = pEffectParam.IsNeedSummarize();
			BTL_POKEPARAM attacker = pEffectParam.GetAttacker();
			var desc = new Section_CureSick.Description();
			desc.pokeID = attacker.GetID();
			desc.sick = WazaSickEx.POKEFULL;
			desc.targetPokeCount = 0;
			desc.isStandardMessageDisable = isNeedSummarize;
			var accessor = new FrontPokeAccessor(GetMainModule(), GetBattleEnv());
			BTL_POKEPARAM target;
			while (accessor.GetNext(out target))
			{
				if (CheckFriendPoke(attacker, target) && target.GetPokeSick() != Sick.NONE)
				{
					desc.targetPokeID[desc.targetPokeCount] = target.GetID();
					desc.targetPokeCount++;
				}
			}
			for (int i = 0; i < desc.targetPokeCount; i++)
			{
				byte pokeID = desc.targetPokeID[i];
				BTL_POKEPARAM bpp = GetPokeParam(pokeID);
				BtlPokePos pos = GetPokePos(pokeID);
				pEffectParam.SetEffected_CureSick(pos, bpp.GetPokeSick());
			}
			var result = new Section_CureSick.Result();
			GetSectionContainer().GetSection_CureSick().Execute(result, desc);
			return result.isCured;
		}
		private bool effect_RecoverHP(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam) {
			BTL_POKEPARAM attacker = pEffectParam.GetAttacker();
			var accessor = new FrontPokeAccessor(GetMainModule(), GetBattleEnv());
			bool isEffected = false;
			BTL_POKEPARAM target;
			while (accessor.GetNext(out target))
			{
				if (!CheckFriendPoke(target, attacker))
					continue;
				var desc = new Section_RecoverHP.Description();
				desc.userPokeID = attacker.GetID();
				desc.targetPokeID = target.GetID();
				desc.isSkipFailCheckSP = false;
				desc.isDisplayRecoverEffect = !pEffectParam.IsNeedSummarize();
				desc.isDisplayFailMessage_HPFull = false;
				desc.isDisplayFailMessage_SP = false;
				desc.recoverHP = (ushort)calc.QuotMaxHP(target, 6, false);
				if (!pEffectParam.IsNeedSummarize())
				{
					desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, (ushort)BTL_STRID_SET.HP_Recover);
					desc.successMessage.AddArg(target.GetID());
				}
				var result = new Section_RecoverHP.Result();
				GetSectionContainer().GetSection_RecoverHP().Execute(result, desc);
				if (result.isRecovered)
				{
					pEffectParam.SetEffected(GetPokePos(target), 51);
					isEffected = true;
				}
			}
			return isEffected;
		}
		private bool effect_DecrementPP(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam) {
			BTL_POKEPARAM attacker = pEffectParam.GetAttacker();
			var accessor = new FrontPokeAccessor(GetMainModule(), GetBattleEnv());
			bool isEffected = false;
			BTL_POKEPARAM target;
			while (accessor.GetNext(out target))
			{
				if (!CheckFriendPoke(attacker, target) && effect_DecrementPP_Target(pEffectParam, target))
				{
					pEffectParam.SetEffected(GetPokePos(target), 50);
					isEffected = true;
				}
			}
			return isEffected;
		}
		private bool effect_DecrementPP_Target(global::Dpr.Battle.Logic.GShockEffectParam pEffectParam, global::Dpr.Battle.Logic.BTL_POKEPARAM pTarget) {
			byte wazaIndex = pTarget.WAZA_SearchIdx(pTarget.GetPrevOrgWazaID());
			var desc = new Section_DecrementPP.Description();
			desc.poke = pTarget;
			desc.volume = 2;
			desc.wazaIndex = wazaIndex;
			var result = new Section_DecrementPP.Result();
			GetSectionContainer().GetSection_DecrementPP().Execute(result, desc);
			if (result.isDecrement && !pEffectParam.IsNeedSummarize())
				GetServerCommandPutter().Message_Set((ushort)BTL_STRID_SET.GShockWave_PP_Reduce, pTarget.GetID());
			return result.isDecrement;
		}
		public class Description
		{
			public global::Dpr.Battle.Logic.BTL_POKEPARAM attacker;
			public global::Dpr.Battle.Logic.BTL_POKEPARAM defender;
			public global::Dpr.Battle.Logic.ActionDesc actionDesc;
			public global::Dpr.Battle.Logic.WazaParam wazaParam;
			public Description() { }
		}
		public class Result
		{
			public bool isEffected;
			public Result() { }
		}
	}
